<div id="toastContainer" class="toast-container"></div>

<script>
(function(){
  'use strict';
  var $$ = document;
  var s_ = $$('#uf');            // alvo do autocomplete de UF
  var STORE = 'bf_bombeiro_v1';
  var UF_DB = [
    ['AC','Rio Branco'],['AL','Maceió'],['AP','Macapá'],['AM','Manaus'],['BA','Salvador'],
    ['CE','Fortaleza'],['DF','Brasília'],['ES','Vitória'],['GO','Goiânia'],['MA','São Luís'],
    ['MT','Cuiabá'],['MS','Campo Grande'],['MG','Belo Horizonte'],['PA','Belém'],
    ['PB','João Pessoa'],['PR','Curitiba'],['PE','Recife'],['PI','Teresina'],['RJ','Rio de Janeiro'],
    ['RN','Natal'],['RS','Porto Alegre'],['RO','Porto Velho'],['RR','Boa Vista'],
    ['SC','Florianópolis'],['SP','São Paulo'],['SE','Aracaju'],['TO','Palmas']
  ];
  var ERR_IDS = [
    {id:'cpf',msg:'#cpfMsg'},{id:'nome',msg:'#nomeMsg'},
    {id:'classe',msg:'#classeMsg'},{id:'id_meta4',msg:'#idMetaMsg'},
    {id:'opm_meta4',msg:'#opmMetaMsg'},{id:'email_meta4',msg:'#emailMsg'},
    {id:'nascimento',msg:'#nascMsg'},{id:'uf',msg:'#ufMsg'},
    {id:'promocao',msg:'#promMsg'},{id:'data_admisso',msg:'#admMsg'}
  ];

  /* ------------------------------------------------------ UTILITÁRIOS */
  function fmtDate(iso){
    if(!iso||iso==='') return '—';
    var d = new Date(Number(iso));
    return isNaN(d.getTime()) ? '—' :
      d.toLocaleDateString('pt-BR',{weekensor:'long',year:'numeric',month:'short',day:'2-digit'}) +
      ' · ' + d.toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit',second:'2-digit'});
  }
  function pickOptions(q){
    var r = [];
    UF_DB.forEach(function(u){
      if(u[0].indexOf(q.charAt(0)) >= 0) r.push(u);
    });
    return r.slice(0,12);
  }
  function nextEl(el,p){
    var n = el.nextElementSibling;
    while(n && n.parentElement !== el.parentNode) n = n.nextElementSibling;
    return n;
  }

  /* --------------------------------------------------------- DV CPF */
  function computeDV1(d){ /* 1º dígito verificador a partir de até 9 dígitos */
    var s = 0;
    for(var i = 0; i < Math.min(d.length, 9); i++){ s += Number(d[i]) * (11 - i); }
    var v = 11 - (s % 11);
    return v >= 10 ? 0 : String(v).padStart(1, '0');
  }
  function computeDV2(d){ /* 2º dígito a partir de 10 dígitos (inclui o 1º DV) */
    var s = 0;
    for(var i = 0; i < 10; i++){ s += Number(d[i]) * (11 - i); }
    var v = 11 - (s % 11);
    return v >= 10 ? 0 : String(v).padStart(1, '0');
  }
  function validateCPFOnly(v){
    v = String(v || '').replace(/\D/g, '').slice(0, 11);
    if(!/^\d{11}$/.test(v)) return false;
    var d = v.split('').map(Number);
    return computeDV1(d.slice(0, 9)) === Number(d[9]) &&
           computeDV2(d.slice(0, 10)) === Number(d[10]);
  }

  /* ----------------------------- MÁSCARA DE CPF ---------------------------- */
  function maskCPF(el){
    el = el || $$[0].activeElement;
    if(!(el instanceof HTMLInputElement || el instanceof HTMLSelectElement)) return;
    if(el.type === 'date') return;            // datas têm tratamento próprio
    var v = String(el.value || '').replace(/\D/g, '').slice(0, 13);
    if(!v){ el.value = ''; return; }
    var ds = v.match(/\d/g) || [];
    if(ds.length <= 9){
      // apenas formatação em grupos de 3, sem dígitos verificadores
      var g = [];
      for(var i = 0; i < ds.length; i += 3) g.push(ds.slice(i, i + 3));
      var rem = ds.slice(g.length * 3);
      el.value = (g.length ? g.join('.') : '') + (rem ? '-' + rem : '');
      return;
    }
    var base = ds.slice(0, 9).join('');
    if(ds.length === 10){
      // o 10º dígito digitado fica "pendente"; só formata
      var g = [];
      for(var i = 0; i < 9; i += 3) g.push(base.slice(i, i + 3));
      el.value = g.join('.') + '-' + ds[9];
      return;
    }
    // >= 11 dígitos: DVs calculados a partir dos 9 primeiros dígitos
    var g = [];
    for(var i = 0; i < 9; i += 3) g.push(base.slice(i, i + 3));
    var dv1 = computeDV1(base);
    var cand = ds.slice(0, 10); // 9 dígitos + 1º dígito usado no cálculo do 2º DV
    var dv2 = computeDV2(cand);
    el.value = g.join('.') + '-' + String(dv1).padStart(1, '0') + String(dv2).padStart(1, '0');
  }

  /* ----------------------------- EVENTO CPF --------------------------------- */
  var $cpf = $$('#cpf');
  $cpf.addEventListener('input', maskCPF);

  /* ------------------------------- DATEDATASE MAX --------------------------- */
  var maxDate = new Date().toISOString().slice(0, 10);
  $$('input[type="date"]').forEach(function(d){ d.setAttribute('max', maxDate); });
  $$('#nascimento').setAttribute('min', '1900-01-01');

  /* ------------------------------ AUTOCOMPLETE DE UF ----------------------- */
  function closeSugg(){
    $$('#uf .uf-suggest').length ? $$('#uf .uf-suggest').remove() : null;
    chosenAbbr = null;
  }
  var chosenAbbr = null, ufSuggTimer = null;
  s_.addEventListener('input', function(){
    clearTimeout(ufSuggTimer);
    var v = this.value.trim().toUpperCase();
    if(!v || v.length < 2){
      ufSuggTimer = setTimeout(closeSugg, 300); return;
    }
    ufSuggTimer = setTimeout(function(){
      closeSugg();
      var items = pickOptions(v.charAt(0));
      var block = document.createElement('div');
      block.className = 'uf-suggest';
      block.style.position = 'absolute';
      block.style.left = '0'; block.style.top = '100%';
      block.style.zIndex = 1072;
      block.style.background = 'rgba(12,14,26,.95)';
      block.style.borderColor = 'rgba(255,255,255,.14)';
      block.style.borderRadius = '.6rem';
      block.style.boxShadow = '0 10px 30px rgba(0,0,0,.6)';
      block.style.padding = '.4rem';
      var list = document.createElement('div');
      if(items.length){
        items.forEach(function(u){
          var it = document.createElement('div');
          it.className = 'uf-item'; it.dataset.val = u[0];
          it.innerHTML = '<span class="uf-it-text">' + u[0] + ' &#8212; ' + u[1] + '</span><kbd class="uf-it-key" aria-hidden="true">&#8594;</kbd>';
          list.appendChild(it);
          it.addEventListener('click', function(){
            chosenAbbr = u[0];
            var o = document.createElement('option');
            o.value = u[0]; o.textContent = u[0] + ' &#8212; ' + u[1];
            s_.appendChild(o);
            var c = s_.querySelectorAll('option:not([disabled])');
            var i = -1;
            for(var k = 0; k < c.length; k++){
              if(c[k].textContent.indexOf(u[0]) > -1){ i = k; break; }
            }
            if(i >= 0){ c[i].classList.add('selected'); s_.selectedIndex = i; }
            s_.value = u[0];
            try{ s_.dispatchEvent(new Event('change', { bubble: true })); }catch(e){}
            clearInterval(ufSuggTimer);
            closeSugg();
            s_.focus();
          });
        });
      } else {
        var nop = document.createElement('div');
        nop.className = 'uf-item uf-it-no';
        nop.innerHTML = '<span class="uf-it-text">Nenhuma UF encontrada &#8212; digite 2 ou mais letras</span>';
        list.appendChild(nop);
      }
      block.appendChild(list);
      s_.after(block);
      Array.prototype.forEach.call(block.querySelectorAll('.uf-item'), function(it){ it.style.cursor = 'pointer'; });
      block.addEventListener('keydown', function(e){
        if(e.key === 'Escape'){ closeSugg(); return; }
        if(e.key === 'Tab'){ clearTimeout(ufSuggTimer); return; }
        var fi = list.firstElementChild;
        if(fi) e.preventDefault(); fi.focus();
      });
      if(list.children.length) list.children[0].focus();
    }, 320);
  });
  s_.addEventListener('change', closeSugg);
  s_.addEventListener('blur', closeSugg);

  /* --------------------------- TOGGLE (RESERVADO) -------------------------- */
  function applyToggleUI(){
    var wrap = $$('.bf-toggle-wrap');
    var onLbl, offLbl, badge;
    try{
      onLbl = wrap[0].querySelector('#resOn');
      offLbl = wrap[0].querySelector('#resOff');
      badge = wrap[0].querySelector('#resBadge');
    }catch(e){}
    Array.prototype.forEach.call(wrap, function(wr){
      var on = wr.querySelector('.toggle') && wr.querySelector('.toggle').checked;
      var tr = wr.querySelector('.bf-toggle-track');
      tr.classList.toggle('on', on);
      tr.setAttribute('aria-checked', String(on));
      onLbl.style.display = on ? 'block' : 'none';
      offLbl.style.display = !on ? 'block' : 'none';
      if(badge){
        badge.textContent = on ? 'ATIVADO' : 'DESATIVADO';
        badge.classList.toggle('text-success', on);
        badge.classList.remove('text-danger');
      }
    });
  }
  var $toggle = $$('.toggle');
  $toggle.forEach(function(t){ t.addEventListener('change', applyToggleUI); });

  $$('.bf-toggle-wrap').addEventListener('click', function(e){
    var tb = this.querySelector('.toggle');
    if(tb){
      if(!e.target.closest('[aria-hidden="true]') && !(e.target.closest('.bf-toggle-desc') || e.target.closest('.bf-status'))){
        tb.checked = !tb.checked;
        applyToggleUI();
      }
    }
    e.stopPropagation();
  });
  $$('.bf-toggle-wrap').addEventListener('keydown', function(e){
    if(e.key === ' ' || e.key === 'Enter'){
      e.preventDefault();
      var tb = this.querySelector('.toggle');
      if(tb){ tb.checked = !tb.checked; applyToggleUI(); }
    }
  });

  /* ------------------------ CHIPS DE SISTEMA / TEMPO ----------------------- */
  function updateSystemChips(){
    var raw = localStorage.getItem(STORE);
    var pkg = raw ? (typeof JSON.parse(raw) === 'object' ? JSON.parse(raw) : null) : null;
    var created = pkg ? (parseInt(pkg.ts, 10) || 0) : Date.now();
    $('#sysCriado').text(fmtDate(new Date(created)));
    $('#sysAtualizado').text(fmtDate(new Date()));
  }
  updateSystemChips();
  setInterval(updateSystemChips, 15000);

  /* ------------------------ RESTAURAÇÃO AO CARREGAR ------------------------ */
  function restoreSaved(){
    try{
      var raw = localStorage.getItem(STORE);
      if(typeof raw !== 'string' || !raw) return;
      var pkg = JSON.parse(raw);
      if(!pkg) return;
      Object.entries(pkg.fields || {}).forEach(function(kv){
        var el = $$(kv[0]);
        if(el) el.value = kv[1];
      });
      if(pkg.reservado !== undefined){
        $toggle.forEach(function(t){ t.checked = !!pkg.reservado; applyToggleUI(); });
      }
    }catch(e){ console.warn('[BF] Restauração falhou:', e); }
  }
  window.addEventListener('load', restoreSaved);

  /* ------------------------- MARCADORES VISUAIS DE ERRO --------------------- */
  function clearMarks(fd){
    ERR_IDS.forEach(function(e){
      var t = $$(e.msg);
      if(t) t.style.display = 'none';
      var pf = t.parentElement;
      if(pf) pf.classList.remove('bf-has-err');
    });
  }
  function setMark(fd, e){
    var t = $$(e.msg);
    if(!t) return;
    t.style.display = '';
    t.parentElement.classList.add('bf-has-err');
  }

  /* --------------------------- SALVAR / VALIDAR ---------------------------- */
  var form = $$('#formBombeiro')[0];
  var btnSave = form.querySelector('button[type="submit"]');

  function hideLoad(){
    $$('#proc').classList.remove('show');
    form.disabled = false;
    btnSave.disabled = false;
  }

  form.addEventListener('submit', function(e){
    e.preventDefault();
    if(form.disabled) return;

    var loading = $$('#proc');
    loading.classList.add('show');
    btnSave.disabled = true;
    var errs = [];

    function chk(id, cond, msg){ if(cond) return; errs.push(id, msg); }

    // CPF — formato
    var cpf = $('#cpf').value;
    chk('cpf', cpf.length === 11 && /^\d{11}$/.test(cpf), 'Informe um CPF válido (000.000.000-00).');
    if(validateCPFOnly(cpf)){} else chk('cpf', false, 'CPF informado não possui dígitos verificadores válidos.');

    // Nome
    chk('nome', $('#nome').value.trim().length >= 2, 'Informe um nome com pelo menos 2 caracteres.');

    // Obrigatórios
    [['id_meta4','#id_meta4'], ['opm_meta4','#opm_meta4'],
      ['email_meta4','#email_meta4'], ['classe','#classe']].forEach(function(gt){
      chk(gt[0], gt[1].value.trim(), gt[0] + ' é obrigatório.');
    });

    // E-mail
    chk('email_meta4', $('#email_meta4').value, 'O e-mail é obrigatório.');
    chk('email_meta4', /^[^@\s]+@[^@\s]+\.[a-zA-Z]{2,}$/.test($('#email_meta4').value), 'Informe um e-mail válido.');

    // Avisos não bloqueantes
    try{
      var p = new Date($('#promocao').value);
      if(!isNaN(p.getTime()) && p > new Date()){
        // aviso coletado depois; aqui só sinalizamos que há algo a conferir
      }
    }catch(_){}

    clearMarks(form);
    if(errs.length){
      var ul = '<ul class="list-group list-group-sm mb-2" style="list-style:none"><li>' +
               errs.map(function(x){ return x[1]; }).join('</li><li>') + '</li></ul>';
      var alertEl = document.createElement('div');
      alertEl.className = 'alert alert-danger bg-dark border border-danger-subtle mb-3';
      alertEl.innerHTML = '<ul class="mb-0 m-0 pe-3 list-unstyled">' + ul + '</ul>' +
                          '<p class="mb-0 text-warning mt-2"><strong>Por favor, corrija os campos destacados acima.</strong></p>';
      form.insertBefore(alertEl, btnSave);
      errs.forEach(setMark);
      alertEl.scrollIntoView({behavior: 'smooth', block: 'nearest'});
      return;
    }

    // ---------- PERSISTÊNCIA ----------
    var pkg = { ts: Date.now(), fields: {} };
    form.querySelectorAll('[id]').forEach(function(el){
      var k = el.id || el.name;
      if(k === 'toggle' || el.matches('input[type=checkbox][class*="toggle]')) return;
      if(typeof el.value !== 'string') return;
      pkg.fields[k] = el.value;
    });

    try{
      localStorage.setItem(STORE, JSON.stringify(pkg));

      // checagem de duplicidade de CPF
      var prev = localStorage.getItem(STORE);
      if(prev){
        try{
          var prior = JSON.parse(prev);
          if(prior.records){
            for(var i = 0; i < prior.records.length; i++){
              if(prior.records[i].cpf === $('#cpf').value){
                errs.push(null, 'Já existe um registro com este CPF — a operação será tratada como <strong>atualização</strong>.');
                break;
              }
            }
          } else{ prior.records = []; }
        }catch(_){ /* ignora */ }
      }
      if(errs.length){ return; }

      SUCCESS(form);
    }catch(err){
      hideLoad();
      showToast('Falha ao gravar os dados (' + err.message + ') — tente novamente.', {title: 'Erro de sistema'});
    }
  });

  function SUCCESS(fd){
    hideLoad();
    btnSave.disabled = false;
    clearMarks(fd);
    updateSystemChips();
    applyToggleUI();
    var hora = new Date().toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit',second:'2-digit'});
    showToast('\u2713 Cadastro salvo com sucesso \u2014 ' + hora, {cls: 'toast-success'});
    try{
      var hist = JSON.parse(localStorage.getItem('bf_hist')) || [];
      hist.push({ cpfSh: $('#cpf').value.slice(0, 6) + '....', dt: new Date().toISOString(), tipo: 'inclusão' });
      localStorage.setItem('bf_hist', JSON.stringify(hist));
    }catch(e){}
  }

  /* ----------------------------- TOASTS ------------------------------------ */
  function showToast(html, opts){
    opts = opts || {};
    var inst = window.bootstrap.Toast.getOrCreateInstance(
      $$('#toastContainer')[0], {
        position: { top: 'center', right: 'center' },
        completionHandler: function(){ this.el.remove(); }
      });
    var cls = (opts.cls ? ' toast ' + opts.cls : '') + ' toast-body';
    var buf = ((opts.title ? (<div class="toast-heading">'+opts.title+'</div>) : '') +
               '<div class="' + cls + '">' + html + '</div>');
    inst.show({html: buf, duration: opts.duration || 5000, complete: inst.hide.bind(inst)});
  }

  /* ------------------------ BOTÕES AUXILIARES ------------------------------- */
  $('#btnCancel').addEventListener('click', function(){
    hideLoad();
    form.reset();
    updateSystemChips();
    applyToggleUI();
    $('#sexoId').text('ID_Sexo: (livre)');
    showToast('Formulário limpo', {cls: 'toast-info'});
  });
  $('#btnClearAll').addEventListener('click', function(){
    if(!confirm('Isso apagar\u00e1 todos os dados salvos localmente e limpar\u00e1 o formulário. Confirmar?')) return;
    try{ localStorage.removeItem(STORE); localStorage.removeItem('bf_hist'); }catch(e){}
    form.reset();
    updateSystemChips();
    applyToggleUI();
    $('#sexoId').text('ID_Sexo: (livre)');
    showToast('Dados locais removidos e formul\u00e1rio limpo', {cls: 'toast-warning'});
  });

  /* ------------------------ SEXO / ID_SEXO ---------------------------------- */
  $('#sexo').addEventListener('change', function(){
    var v = this.value;
    var chip = $('#sexoId');
    if(v === ''){ chip.textContent = 'ID_Sexo: (livre)'; }
    else{
      var n = parseInt(v, 10);
      var nomes = {'0':'Não informado','1':'Masculino','2':'Feminino','3':'Preferência não informada'};
      chip.textContent = 'ID_Sexo: ' + n + ' &#9882;' + (nomes[v] || '');
    }
  });

  /* ------------------------ INICIALIZAÇÃO ----------------------------------- */
  function init(){
    // constrói a lista de UFs (AB – Capital)
    s_.empty();
    var opt1 = document.createElement('option');
    opt1.value = ''; opt1.disabled = true;
    opt1.textContent = 'Selecione o estado…';
    s_.appendChild(opt1);
    UF_DB.forEach(function(u){
      var o = document.createElement('option');
      o.value = u[0]; o.textContent = u[0] + ' &#8212; ' + u[1]; o.classList.add('uf-opt');
      s_.appendChild(o);
    });
  }
  if(document.readyState === 'loading'){ document.addEventListener('DOMContentLoaded', init); }
  else init();

})();
</script>
